<?php
namespace App\Controllers; use App\Services\VerificationAssistanceService; use DomainException;
final class VerificationAssistanceController extends BaseController { protected $helpers=['form','url'];public function form():string{return view('auth/verification_assistance',['title'=>'Request Verification Assistance']);}public function submit(){try{(new VerificationAssistanceService())->submit($this->request->getPost(),$this->request->getFile('supporting_document'));return redirect()->to(site_url('verification-assistance'))->with('success','Your request was received by Student Records. Please wait for external contact, then retry registration.');}catch(DomainException $e){return redirect()->to(site_url('verification-assistance'))->with('error',$e->getMessage())->with('assistance_form',$this->safeInput());}}private function safeInput():array{$p=$this->request->getPost();return array_intersect_key(is_array($p)?$p:[],array_flip(['student_id','full_name','contact_email','program','explanation']));}}
